#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int longestBalanced(string s) {
        int n = s.size(), ans = 0;
        for (int i = 0, j; i < n; i = j) {
            j = i + 1;
            while (j < n && s[j] == s[i]) ++j;
            ans = max(ans, j - i);
        }
        for (int a = 0; a < 3; ++a) {
            for (int b = a + 1; b < 3; ++b) {
                unordered_map<int,int> first;
                first[0] = -1;
                int diff = 0;
                for (int i = 0; i < n; ++i) {
                    int c = s[i] - 'a';
                    if (c != a && c != b) {
                        first.clear(); first[0] = i; diff = 0;
                    } else {
                        diff += (c == a ? 1 : -1);
                        if (first.count(diff)) ans = max(ans, i - first[diff]);
                        else first[diff] = i;
                    }
                }
            }
        }
        unordered_map<long long,int> first;
        first[(long long)n * (2LL*n + 1) + n] = -1;
        int cnt[3] = {0,0,0};
        for (int i = 0; i < n; ++i) {
            ++cnt[s[i] - 'a'];
            long long x = (long long)cnt[0] - cnt[1];
            long long y = (long long)cnt[0] - cnt[2];
            long long key = (x + n) * (2LL*n + 1) + (y + n);
            if (first.count(key)) ans = max(ans, i - first[key]);
            else first[key] = i;
        }
        return ans;
    }
};
